public class Main {
    public static void main(String[] args) {
        int marks = 72; //~ The value being tested.
        if (marks >= 90) { //~ Is 72 >= 90? No, so this block is skipped.
            System.out.println("A");
        } else if (marks >= 60) { //~ Is 72 >= 60? Yes, so this block runs and every later branch is skipped.
            System.out.println("B"); //~ Prints B.
        } else {
            System.out.println("C");
        }
        System.out.println("done"); //~ After the whole if-chain, the program carries on as normal.
    }
}

